import os
import json
from datetime import datetime

def validate_input(parameters):
    if 'cpu_threshold' not in parameters or 'memory_threshold' not in parameters:
        return False, 'Missing required parameter: cpu_threshold and memory_threshold'

    if isinstance(parameters['cpu_threshold'], float) and 0 <= parameters['cpu_threshold'] <= 100:
        pass
    else:
        return False, 'Invalid value for cpu_threshold. Must be a number between 0 and 100.'

    if isinstance(parameters['memory_threshold'], int) and 0 <= parameters['memory_threshold'] <= 100:
        pass
    else:
        return False, 'Invalid value for memory_threshold. Must be an integer between 0 and 100.'

    return True, None

def get_system_resources():
    cpu_usage = os.popen('top -bn1 | grep "Cpu(s)" | awk \'{print $2 + $4}\'').read().strip()
    if not cpu_usage:
        return None
    memory_usage = os.popen('free -m | awk \'NR==2{printf "%s %s\n", $2, $3}\'').read().strip()
    disk_usage = os.popen('df -h / | grep "/" | awk \'{print $5}\'').read().strip()

    return {
        'cpu': float(cpu_usage),
        'memory': int(memory_usage.split()[1]),
        'disk': disk_usage
    }

def generate_report(thresholds, resources):
    report = {'timestamp': datetime.now().isoformat(), 'status': 'ok', 'details': {}}

    for key in thresholds:
        if resources[key] > thresholds[key]:
            report['status'] = 'warning'
            report['details'][key] = f'{resources[key]} ({thresholds[key]})'

    return json.dumps(report, indent=2)

def main():
    parameters = {
        'cpu_threshold': 80,
        'memory_threshold': 90
    }

    if not validate_input(parameters):
        print(f'Error: {validate_input(parameters)[1]}')
        exit(1)

    resources = get_system_resources()
    if resources is None:
        print('Failed to retrieve system resource usage.')
        exit(1)

    report = generate_report(parameters, resources)
    print(report)

if __name__ == '__main__':
    main()
