class MethodologyCollaborator:
    def __init__(self):
        self.proposed_algorithm = None
        self.endpoints_list = []

    def propose_integration(self, algorithm_description, endpoints):
        if not algorithm_description or not isinstance(endpoints, list) or len(endpoints) == 0:
            return {"status": "rejected", "reason": "Invalid input"}

        # Validate proposed algorithm does not conflict with existing endpoints
        for endpoint in self.endpoints_list:
            if endpoint['method'] == algorithm_description['method'] and endpoint['path'] == algorithm_description['path']:
                return {"status": "rejected", "reason": f"Conflict detected: {algorithm_description['method']}/{algorithm_description['path']} already exists"}

        # Prepare response
        response = {
            "status": "approved",
            "reason": None,
            "endpoint_conflict": False
        }

        if self.endpoints_list:
            response["endpoint_conflict"] = True

        return json.dumps(response)

